<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/css/app.css"><title>کاربران | آزمون‌یار</title></head><body><header><b>✓ آزمون‌یار</b><nav><a href="/dashboard">داشبورد</a><a href="/projects">پروژه‌ها</a><a href="/test-cases">سناریوها</a><a href="/test-runs">دوره‌های تست</a><a href="/my-tasks">کارتابل من</a><a href="/defects">خطاها</a><a href="/admin/users">کاربران</a></nav><form method="post" action="/logout"><?=csrf_field()?><button>خروج</button></form></header><main class="app"><span>مدیریت سیستم</span><h1>کاربران و نقش‌ها</h1><?php if(session('message')):?><div class="alert"><?=esc(session('message'))?></div><?php endif ?><?php if(session('error')):?><div class="alert error"><?=esc(session('error'))?></div><?php endif ?><section><h2>کاربر جدید</h2><form method="post" class="grid"><?=csrf_field()?><label>نام نمایشی<input name="display_name" required></label><label>نام کاربری<input name="username" required></label><label>ایمیل<input name="email" type="email"></label><label>نقش<select name="role_id" required><option value="">انتخاب نقش</option><?php foreach($roles as $role):?><option value="<?=$role['id']?>"><?=esc($role['name'])?></option><?php endforeach?></select></label><label>رمز موقت<input name="password" type="password" minlength="12" required></label><label><input name="is_admin" type="checkbox" value="1"> مدیر سیستم</label><button class="btn">ایجاد کاربر</button></form></section><section><h2>گرید کاربران</h2><div class="grid-toolbar"><input data-grid-search="#users-grid" placeholder="جست‌وجوی نام یا نقش…"></div><div class="table-wrap"><table id="users-grid"><tr><th>کاربر</th><th>نام</th><th>نقش</th><th>مدیر</th><th>وضعیت</th></tr><?php foreach($users as $user):?><tr><td><?=esc($user['username'])?></td><td><?=esc($user['display_name'])?></td><td><?=esc($user['role_name']??'—')?></td><td><?=$user['is_admin']?'بله':'خیر'?></td><td><i><?=$user['is_active']?'فعال':'غیرفعال'?></i></td></tr><?php endforeach?></table></div></section></main><script src="/assets/js/app.js"></script></body></html>
